#include <stddef.h>
#include <stdint.h>

// Ask for a factory reset. The strip flashes amber three times, then pixcFactoryWipeNow() runs
// from the loop. `why` goes to the debug log ("cloud", "power-cycle").
void pixcRequestFactoryReset(const char* why);
bool pixcFactoryResetPending();

// Format LittleFS (cfg, wsec with every key, presets, everything), erase the Wi-Fi configuration
// in NVS, the usermod's own NVS namespaces (reset counter, pending login, energy log) and any crash
// dump, then restart. Keeps `pixc_fac` (the factory hotspot password) and `pixc_ota` (the
// anti-rollback floor): a reset must not make a unit accept an older signed image, and the
// password printed on its label must keep working. Does not return.
[[noreturn]] void pixcFactoryWipeNow();

// Reboot `ms` from now, from the loop (so a reply can leave first).
void pixcRebootAfter(uint32_t ms);

// Call once, early in setup: loads the power-cycle gesture from NVS, counts the previous boot if
// it stayed up 1.5-6 s, and requests the reset when that made five in a row (pixc::ResetGesture).
void pixcBootCounterOnBoot();
// Call every loop: arms this boot at 1.5 s, clears the chain at 6 s, and runs a pending reset.
void pixcDeviceLoop();

// The per-unit hotspot password from factory NVS (`pixc_fac/ap_psk`), or the dev fallback
// PIXC_DEV_AP_PSK. False when there is none: a release build then does not open the hotspot.
bool pixcFactoryApPsk(char* out, size_t cap);

// A random 32-bit value drawn at boot, as 8 lowercase hex characters. Returned by GET /json/id and
// bound into every LAN request signature, so a request captured before a reboot never replays.
const char* pixcBootId();

// The power plan's brightness cap (`pixc.bri_max` on /cfg, kept in cfg.json as
// um.PixcConnect.bri_max): 1-255, 255 when the cloud sent none. Only the cloud sets it
// (pixc_logic.h). WS2812FX::setBrightness() and scaledBri() hold the strip under it, whatever drives
// it (a state write, a preset, a transition, DDP); deserializeState() and stateUpdated() hold the
// light's `bri` under it, so the level it reports is the level it shows.
extern uint8_t pixcBriMax;

// A cap from the cloud (pixc::validBriMax, else ignored). A light above it dims to it at once and
// reports the new level; a stream (DDP) is capped at once too. True when the cap changed.
bool pixcSetBriMax(int cap);
